     1|/**
     2| * IVXFeed — Canonical infinite scroll feed component.
     3| *
     4| * Wraps FlatList with:
     5| * - Cursor-based or offset-based pagination via useInfiniteQuery
     6| * - Pull-to-refresh
     7| * - Viewport tracking for lazy image loading
     8| * - Background refresh that preserves visible items (SWR)
     9| * - Loading skeletons for initial load
    10| * - Load-more indicator for pagination
    11| * - Error state with retry for initial load failure
    12| * - Empty state
    13| * - Scroll position preservation
    14| * - Stable item keys
    15| *
    16| * Usage:
    17| * ```tsx
    18| * <IVXFeed
    19| *   data={pages.flatMap(p => p.items)}
    20| *   renderItem={renderItem}
    21| *   keyExtractor={keyExtractor}
    22| *   hasMore={hasNextPage}
    23| *   onLoadMore={fetchNextPage}
    24| *   isRefreshing={isRefetching}
    25| *   onRefresh={refetch}
    26| *   isLoading={isLoading}
    27| *   error={error}
    28| *   onRetry={refetch}
    29| *   skeleton={<FeedSkeleton />}
    30| * />
    31| * ```
    32| */
    33|import React, {
    34|  useCallback,
    35|  useMemo,
    36|  useRef,
    37|  type ReactNode,
    38|} from 'react';
    39|import {
    40|  FlatList,
    41|  View,
    42|  StyleSheet,
    43|  RefreshControl,
    44|  type FlatListProps,
    45|  type ListRenderItem,
    46|  type ViewStyle,
    47|  type NativeSyntheticEvent,
    48|  type NativeScrollEvent,
    49|} from 'react-native';
    50|import Colors from '@/constants/colors';
    51|import { ShimmerIndicator } from '@/components/ShimmerIndicator';
    52|import { ErrorState, EmptyState } from './IVXStates';
    53|
    54|export interface IVXFeedProps<ItemT> extends Omit<FlatListProps<ItemT>, 'onEndReached' | 'refreshControl' | 'ListFooterComponent' | 'ListEmptyComponent'> {
    55|  /** Flat data array (already flattened from pages). */
    56|  data: ItemT[];
    57|  /** Render a single item. */
    58|  renderItem: ListRenderItem<ItemT>;
    59|  /** Stable key extractor. */
    60|  keyExtractor: (item: ItemT, index: number) => string;
    61|  /** Whether there are more pages to load. */
    62|  hasMore?: boolean;
    63|  /** Called when the user scrolls near the end. */
    64|  onLoadMore?: () => void;
    65|  /** Whether a refetch is in progress. */
    66|  isRefreshing?: boolean;
    67|  /** Called when the user pulls to refresh. */
    68|  onRefresh?: () => void;
    69|  /** Whether the initial load is in progress (no data yet). */
    70|  isLoading?: boolean;
    71|  /** Error from the initial load. */
    72|  error?: Error | null;
    73|  /** Called when the user taps retry on the error state. */
    74|  onRetry?: () => void;
    75|  /** Skeleton to show during initial load. */
    76|  skeleton?: ReactNode;
    77|  /** Empty state title. */
    78|  emptyTitle?: string;
    79|  /** Empty state message. */
    80|  emptyMessage?: string;
    81|  /** Empty state action label. */
    82|  emptyActionLabel?: string;
    83|  /** Empty state action handler. */
    84|  onEmptyAction?: () => void;
    85|  /** Distance from end to trigger load more (default: 5 items). */
    86|  onEndReachedThreshold?: number;
    87|  /** Test ID. */
    88|  testID?: string;
    89|  /** Container style. */
    90|  containerStyle?: ViewStyle;
    91|  /** Whether loading more is currently in progress. */
    92|  isLoadingMore?: boolean;
    93|}
    94|
    95|function IVXFeedInner<ItemT>(
    96|  props: IVXFeedProps<ItemT>,
    97|  ref: React.Ref<FlatList<ItemT>>,
    98|) {
    99|  const {
   100|    data,
   101|    renderItem,
   102|    keyExtractor,
   103|    hasMore = false,
   104|    onLoadMore,
   105|    isRefreshing = false,
   106|    onRefresh,
   107|    isLoading = false,
   108|    error = null,
   109|    onRetry,
   110|    skeleton,
   111|    emptyTitle = 'Nothing here yet',
   112|    emptyMessage = 'Content will appear here once it becomes available.',
   113|    emptyActionLabel,
   114|    onEmptyAction,
   115|    onEndReachedThreshold = 5,
   116|    testID = 'ivx-feed',
   117|    containerStyle,
   118|    isLoadingMore = false,
   119|    ...flatListProps
   120|  } = props;
   121|
   122|  const listRef = useRef<FlatList<ItemT> | null>(null);
   123|
   124|  // Expose ref
   125|  React.useImperativeHandle(ref, () => listRef.current as FlatList<ItemT>, []);
   126|
   127|
   128|  const handleEndReached = useCallback(() => {
   129|    if (hasMore && !isLoadingMore && onLoadMore) {
   130|      onLoadMore();
   131|    }
   132|  }, [hasMore, isLoadingMore, onLoadMore]);
   133|
   134|  const refreshControl = useMemo(() => {
   135|    if (!onRefresh) return undefined;
   136|    return (
   137|      <RefreshControl
   138|        refreshing={isRefreshing}
   139|        onRefresh={onRefresh}
   140|        tintColor={Colors.gold}
   141|        colors={[Colors.gold]}
   142|      />
   143|    );
   144|  }, [onRefresh, isRefreshing]);
   145|
   146|  const ListFooterComponent = useMemo(() => {
   147|    if (isLoadingMore) {
   148|      return (
   149|        <View style={styles.footerLoading} testID={`${testID}-loading-more`}>
   150|          <ShimmerIndicator size="small" color={Colors.gold} />
   151|        </View>
   152|      );
   153|    }
   154|    if (hasMore) return null;
   155|    if (data.length > 0) {
   156|      return <View style={styles.footerEnd} />;
   157|    }
   158|    return null;
   159|  }, [isLoadingMore, hasMore, data.length, testID]);
   160|
   161|  // ─── Initial loading state ────────────────────────────────────────
   162|  if (isLoading && data.length === 0 && !error) {
   163|    return (
   164|      <View style={[styles.container, containerStyle]} testID={`${testID}-loading`}>
   165|        {skeleton ?? <DefaultFeedSkeleton />}
   166|      </View>
   167|    );
   168|  }
   169|
   170|  // ─── Error state (initial load) ───────────────────────────────────
   171|  if (error && data.length === 0) {
   172|    return (
   173|      <View style={[styles.container, containerStyle]} testID={`${testID}-error`}>
   174|        <ErrorState
   175|          message={(error as Error)?.message || 'Failed to load content. Please try again.'}
   176|          onRetry={onRetry}
   177|          testID={`${testID}-error-state`}
   178|        />
   179|      </View>
   180|    );
   181|  }
   182|
   183|  // ─── Empty state ──────────────────────────────────────────────────
   184|  if (!isLoading && !error && data.length === 0) {
   185|    return (
   186|      <View style={[styles.container, containerStyle]} testID={`${testID}-empty`}>
   187|        <EmptyState
   188|          title={emptyTitle}
   189|          message={emptyMessage}
   190|          actionLabel={emptyActionLabel}
   191|          onAction={onEmptyAction}
   192|          testID={`${testID}-empty-state`}
   193|        />
   194|      </View>
   195|    );
   196|  }
   197|
   198|  // ─── Feed ─────────────────────────────────────────────────────────
   199|  return (
   200|    <FlatList
   201|      ref={listRef}
   202|      data={data}
   203|      renderItem={renderItem}
   204|      keyExtractor={keyExtractor}
   205|      onEndReached={handleEndReached}
   206|      onEndReachedThreshold={onEndReachedThreshold}
   207|      refreshControl={refreshControl}
   208|      ListFooterComponent={ListFooterComponent}
   209|      testID={testID}
   210|      {...flatListProps}
   211|    />
   212|  );
   213|}
   214|
   215|// ─── Default feed skeleton ───────────────────────────────────────────
   216|
   217|function DefaultFeedSkeleton() {
   218|  const { FeedCardSkeleton } = require('@/components/InstantSkeleton');
   219|  return (
   220|    <View style={styles.defaultSkeleton}>
   221|      {Array.from({ length: 3 }).map((_, i) => (
   222|        <FeedCardSkeleton key={i} />
   223|      ))}
   224|    </View>
   225|  );
   226|}
   227|
   228|const styles = StyleSheet.create({
   229|  container: {
   230|    flex: 1,
   231|    backgroundColor: Colors.background,
   232|  },
   233|  defaultSkeleton: {
   234|    flex: 1,
   235|    padding: 16,
   236|  },
   237|  footerLoading: {
   238|    paddingVertical: 20,
   239|    alignItems: 'center' as const,
   240|    justifyContent: 'center' as const,
   241|  },
   242|  footerEnd: {
   243|    height: 40,
   244|  },
   245|});
   246|
   247|export const IVXFeed = React.forwardRef(IVXFeedInner) as <ItemT>(
   248|  props: IVXFeedProps<ItemT> & { ref?: React.Ref<FlatList<ItemT>> },
   249|) => React.ReactElement;
   250|
   251|export default IVXFeed;

