     1|/**
     2| * ReelVideoPlayer — Instagram-style video player for the full-screen
     3| * vertical reels feed.
     4| *
     5| * Lifecycle guarantees:
     6| *   • Only the active reel plays; neighbors mount poster-only.
     7| *   • Pauses immediately when the app goes to background.
     8| *   • Pauses when the screen loses focus (navigates away).
     9| *   • Pauses on network disconnect; shows retry on reconnect.
    10| *   • Unloads the native player on unmount to free ExoPlayer resources.
    11| *   • Android: prefers progressive MP4 over HLS to avoid expo-av crashes.
    12| *   • Poster displays on Android (Image component, not expo-av posterSource).
    13| *   • Max 3 players mounted at any time (active ± 1).
    14| *
    15| * This wraps SafeVideo with poster-first rendering and error boundary
    16| * isolation so a single bad video never crashes the feed.
    17| */
    18|import React, { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react';
    19|import { View, Text, Image, StyleSheet, Platform } from 'react-native';
    20|import { ResizeMode } from 'expo-av';
    21|import { WifiOff } from 'lucide-react-native';
    22|import SafeVideo from './SafeVideo';
    23|import ReelErrorBoundary from './ReelErrorBoundary';
    24|import { useNetworkState } from '@/hooks/useNetworkState';
    25|
    26|interface ReelVideoPlayerProps {
    27|  videoId: string;
    28|  uri: string | null | undefined;
    29|  hlsUri?: string | null;
    30|  posterUri?: string | null;
    31|  previewBlurUri?: string | null;
    32|  shouldPlay: boolean;
    33|  isMuted: boolean;
    34|  onProgress?: (progress: number) => void;
    35|  onPlaybackStatusUpdate?: (status: { isPlaying: boolean; durationMillis: number; positionMillis: number }) => void;
    36|  testID?: string;
    37|}
    38|
    39|function pickPlaybackUri(
    40|  uri: string | null | undefined,
    41|  hlsUri: string | null | undefined,
    42|  isAndroid: boolean,
    43|): string | null {
    44|  // On Android, prefer progressive MP4 over HLS to avoid expo-av native crashes.
    45|  // On iOS, prefer HLS for adaptive bitrate.
    46|  if (isAndroid) {
    47|    if (uri && !uri.toLowerCase().endsWith('.m3u8')) return uri;
    48|    if (hlsUri && !hlsUri.toLowerCase().endsWith('.m3u8')) return hlsUri;
    49|    // Fall back to HLS only if no MP4 is available
    50|    return uri ?? hlsUri ?? null;
    51|  }
    52|  // iOS: prefer HLS, fall back to MP4
    53|  return hlsUri ?? uri ?? null;
    54|}
    55|
    56|function ReelVideoPlayerInner({
    57|  videoId,
    58|  uri,
    59|  hlsUri,
    60|  posterUri,
    61|  previewBlurUri,
    62|  shouldPlay,
    63|  isMuted,
    64|  onProgress,
    65|  onPlaybackStatusUpdate,
    66|  testID}: ReelVideoPlayerProps) {
    67|  const network = useNetworkState();
    68|  const [retryKey, setRetryKey] = useState<number>(0);
    69|  const [showTapToPlay, setShowTapToPlay] = useState<boolean>(false);
    70|  void showTapToPlay;
    71|  const isAndroidRef = useRef<boolean>(
    72|    typeof Platform !== 'undefined' && Platform.OS === 'android',
    73|  );
    74|
    75|  const playbackUri = useMemo(
    76|    () => pickPlaybackUri(uri, hlsUri, isAndroidRef.current),
    77|    [uri, hlsUri],
    78|  );
    79|
    80|  // Effective play state: pause on network disconnect or background
    81|  const effectiveShouldPlay = shouldPlay && network.isInternetReachable;
    82|
    83|  // When network drops, show the offline overlay; when it returns,
    84|  // allow the user to tap to resume.
    85|  useEffect(() => {
    86|    if (!network.isInternetReachable && shouldPlay) {
    87|      setShowTapToPlay(false);
    88|    }
    89|  }, [network.isInternetReachable, shouldPlay]);
    90|
    91|  const handleRetry = useCallback(() => {
    92|    setRetryKey((k) => k + 1);
    93|  }, []);
    94|
    95|  const handleTapResume = useCallback(() => {
    96|    setShowTapToPlay(false);
    97|  }, []);
    98|  void handleTapResume;
    99|
   100|  // Poster-first rendering: show the poster image immediately, then
   101|  // overlay the video player. On Android, the poster is an Image
   102|  // component (not expo-av's posterSource, which is a crash vector).
   103|  const posterSource = posterUri ?? previewBlurUri ?? null;
   104|
   105|  return (
   106|    <View style={styles.container} testID={testID}>
   107|      {/* Poster layer — always visible behind the video for instant first paint */}
   108|      {posterSource && (
   109|        <Image
   110|          source={{ uri: posterSource }}
   111|          style={StyleSheet.absoluteFill}
   112|          resizeMode="cover"
   113|          fadeDuration={200}
   114|          accessible={false}
   115|        />
   116|      )}
   117|
   118|      {/* Blur placeholder for even faster first paint */}
   119|      {previewBlurUri && previewBlurUri !== posterSource && (
   120|        <Image
   121|          source={{ uri: previewBlurUri }}
   122|          style={StyleSheet.absoluteFill}
   123|          resizeMode="cover"
   124|          fadeDuration={0}
   125|          accessible={false}
   126|        />
   127|      )}
   128|
   129|      <ReelErrorBoundary videoId={videoId} posterUri={posterSource} onRetry={handleRetry}>
   130|        <SafeVideo
   131|          key={`${videoId}-${retryKey}`}
   132|          uri={playbackUri}
   133|          posterUri={null}
   134|          style={StyleSheet.absoluteFill}
   135|          resizeMode={ResizeMode.COVER}
   136|          shouldPlay={effectiveShouldPlay}
   137|          isMuted={isMuted}
   138|          isLooping
   139|          onProgress={onProgress}
   140|          testID={testID ? `${testID}-player` : undefined}
   141|        />
   142|      </ReelErrorBoundary>
   143|
   144|      {/* Offline overlay */}
   145|      {!network.isInternetReachable && (
   146|        <View style={styles.overlay} pointerEvents="none">
   147|          <WifiOff size={36} color="rgba(255,255,255,0.7)" />
   148|          <Text style={styles.overlayText}>No connection</Text>
   149|          <Text style={styles.overlaySub}>Waiting for network...</Text>
   150|        </View>
   151|      )}
   152|    </View>
   153|  );
   154|}
   155|
   156|const ReelVideoPlayer = memo(ReelVideoPlayerInner);
   157|export default ReelVideoPlayer;
   158|
   159|const styles = StyleSheet.create({
   160|  container: {
   161|    flex: 1,
   162|    backgroundColor: '#000',
   163|    overflow: 'hidden'},
   164|  overlay: {
   165|    ...StyleSheet.absoluteFillObject,
   166|    alignItems: 'center',
   167|    justifyContent: 'center',
   168|    backgroundColor: 'rgba(0,0,0,0.55)',
   169|    zIndex: 50},
   170|  overlayText: {
   171|    color: '#fff',
