     1|/**
     2| * useInfiniteFeed — Canonical cursor/offset-based pagination hook.
     3| *
     4| * Wraps useInfiniteQuery with IVX-specific defaults:
     5| * - Stale-while-revalidate (keepPreviousData)
     6| * - Cursor or offset pagination
     7| * - Automatic deduplication
     8| * - Pull-to-refresh support
     9| * - Load-more state tracking
    10| *
    11| * Usage:
    12| * ```tsx
    13| * const {
    14| *   data,
    15| *   isLoading,
    16| *   error,
    17| *   hasMore,
    18| *   loadMore,
    19| *   refresh,
    20| *   isRefreshing,
    21| *   isLoadingMore,
    22| *   flatData,
    23| * } = useInfiniteFeed({
    24| *   queryKey: ['projects'],
    25| *   fetchPage: async (page) => {
    26| *     const res = await fetch(`/api/projects?cursor=${page.cursor}`);
    27| *     return { items: res.data, nextCursor: res.nextCursor };
    28| *   },
    29| * });
    30| * ```
    31| */
    32|import { useMemo, useCallback } from 'react';
    33|import {
    34|  useInfiniteQuery,
    35|  type InfiniteData,
    36|  type UseInfiniteQueryResult,
    37|} from '@tanstack/react-query';
    38|
    39|// ─── Types ───────────────────────────────────────────────────────────
    40|
    41|export interface FeedPage<T> {
    42|  items: T[];
    43|  nextCursor?: string | number | null;
    44|  hasMore?: boolean;
    45|}
    46|
    47|export interface UseInfiniteFeedOptions<T> {
    48|  /** Unique query key array. */
    49|  queryKey: string[];
    50|  /** Fetch a single page. Receives the previous page's nextCursor (or undefined for first page). */
    51|  fetchPage: (cursor: string | number | undefined) => Promise<FeedPage<T>>;
    52|  /** Initial cursor (default: undefined = first page). */
    53|  initialCursor?: string | number | undefined;
    54|  /** Stale time in ms (default: 5 min — matches app QueryClient). */
    55|  staleTime?: number;
    56|  /** Whether the query is enabled. */
    57|  enabled?: boolean;
    58|  /** Number of pages to keep in memory (default: kept by gcTime). */
    59|  maxPages?: number;
    60|}
    61|
    62|export interface UseInfiniteFeedResult<T> {
    63|  /** The raw infinite query result. */
    64|  queryResult: UseInfiniteQueryResult<InfiniteData<FeedPage<T>>>;
    65|  /** Flattened items from all pages. */
    66|  flatData: T[];
    67|  /** Whether the initial load is in progress. */
    68|  isLoading: boolean;
    69|  /** Whether a refetch is in progress. */
    70|  isRefreshing: boolean;
    71|  /** Whether the next page is loading. */
    72|  isLoadingMore: boolean;
    73|  /** Error from the query. */
    74|  error: Error | null;
    75|  /** Whether there are more pages to load. */
    76|  hasMore: boolean;
    77|  /** Fetch the next page. */
    78|  loadMore: () => void;
    79|  /** Refetch from the first page. */
    80|  refresh: () => void;
    81|  /** Total item count across all pages. */
    82|  totalCount: number;
    83|}
    84|
    85|// ─── Hook ────────────────────────────────────────────────────────────
    86|
    87|export function useInfiniteFeed<T>(options: UseInfiniteFeedOptions<T>): UseInfiniteFeedResult<T> {
    88|  const {
    89|    queryKey,
    90|    fetchPage,
    91|    initialCursor,
    92|    staleTime = 5 * 60_000,
    93|    enabled = true,
    94|    maxPages,
    95|  } = options;
    96|
    97|  const queryResult = useInfiniteQuery<FeedPage<T>, Error>({
    98|    queryKey,
    99|    queryFn: ({ pageParam }) => fetchPage(pageParam as string | number | undefined),
   100|    initialPageParam: initialCursor,
   101|    getNextPageParam: (lastPage) => {
   102|      if (lastPage.hasMore === false) return undefined;
   103|      return lastPage.nextCursor ?? undefined;
   104|    },
   105|    staleTime,
   106|    enabled,
   107|    ...(maxPages ? { maxPages } : {}),
   108|  });
   109|
   110|  // Flatten all pages into a single array
   111|  const flatData = useMemo<T[]>(() => {
   112|    if (!queryResult.data?.pages) return [];
   113|    return queryResult.data.pages.flatMap((page) => page.items);
   114|  }, [queryResult.data]);
   115|
   116|  const totalCount = useMemo(() => flatData.length, [flatData]);
   117|
   118|  const hasMore = useMemo(() => {
   119|    if (!queryResult.data?.pages) return false;
   120|    const lastPage = queryResult.data.pages[queryResult.data.pages.length - 1];
   121|    if (!lastPage) return false;
   122|    return (lastPage.hasMore ?? (lastPage.nextCursor != null)) && queryResult.hasNextPage;
   123|  }, [queryResult.data, queryResult.hasNextPage]);
   124|
   125|  const loadMore = useCallback(() => {
   126|    if (queryResult.hasNextPage && !queryResult.isFetchingNextPage) {
   127|      void queryResult.fetchNextPage();
   128|    }
   129|  }, [queryResult]);
   130|
   131|  const refresh = useCallback(() => {
   132|    void queryResult.refetch();
   133|  }, [queryResult]);
   134|
   135|  return {
   136|    queryResult,
   137|    flatData,
   138|    isLoading: queryResult.isLoading,
   139|    isRefreshing: queryResult.isRefetching,
   140|    isLoadingMore: queryResult.isFetchingNextPage,
   141|    error: queryResult.error,
   142|    hasMore,
   143|    loadMore,
   144|    refresh,
   145|    totalCount,
   146|  };
   147|}
   148|
   149|export default useInfiniteFeed;

