    75|  fn: () => Promise<T>,
    76|  label: string,
    77|): Promise<T> {
    78|  let lastError: Error | null = null;
    79|  for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
    80|    try {
    81|      return await fn();
    82|    } catch (err) {
    83|      lastError = err as Error;
    84|      const waitMs = RETRY_BASE_DELAY_MS * Math.pow(2, attempt);
