   520|    console.log('[PhotoUpload] Web original dimensions:', w, 'x', h, 'size:', (blob.size / 1024).toFixed(0), 'KB');
   521|
   522|    if (w > MAX_DIMENSION || h > MAX_DIMENSION) {
   523|      const ratio = Math.min(MAX_DIMENSION / w, MAX_DIMENSION / h);
   524|      w = Math.round(w * ratio);
   525|      h = Math.round(h * ratio);
   526|      console.log('[PhotoUpload] Web scaled to:', w, 'x', h);
   527|    }
   528|
   529|    const canvas = new OffscreenCanvas(w, h);
   530|    const ctx = canvas.getContext('2d');
   531|    if (!ctx) return { blob, mimeType };
   532|    ctx.drawImage(bitmap, 0, 0, w, h);
   533|
   534|    let compressed = await canvas.convertToBlob({ type: 'image/jpeg', quality: COMPRESSION_QUALITY_WEB });
