   537|    if (compressed.size > MAX_WEB_SIZE_KB * 1024) {
   538|      const retryW = Math.round(w * COMPRESSION_RETRY_DIM_FACTOR);
   539|      const retryH = Math.round(h * COMPRESSION_RETRY_DIM_FACTOR);
   540|      const retryCanvas = new OffscreenCanvas(retryW, retryH);
   541|      const retryCtx = retryCanvas.getContext('2d');
   542|      if (retryCtx) {
   543|        retryCtx.drawImage(bitmap, 0, 0, retryW, retryH);
   544|        compressed = await retryCanvas.convertToBlob({ type: 'image/jpeg', quality: COMPRESSION_QUALITY_WEB_RETRY });
   545|        console.log('[PhotoUpload] Web re-compress:', (compressed.size / 1024).toFixed(0), 'KB at', retryW, 'x', retryH);
   546|      }
   547|    }
   548|    bitmap.close();
   549|    return { blob: compressed, mimeType: 'image/jpeg' };
