   850|    if (Platform.OS === 'web') return;
   851|
   852|    for (const uri of uris) {
   853|      if (uri.startsWith('file://') || uri.startsWith('content://') || uri.startsWith('ph://')) {
   854|        try {
   855|          const ext = getMimeAndExt(uri).ext;
   856|          const cachePath = `${FileSystem.cacheDirectory}queued_${Date.now()}_${Math.random().toString(36).substring(2, 6)}.${ext}`;
   857|          await FileSystem.copyAsync({ from: uri, to: cachePath });
   858|          const info = await FileSystem.getInfoAsync(cachePath);
   859|          if (info.exists) {
   860|            cachedUris.push(cachePath);
   861|            console.log('[PhotoUpload] Queued: cached file for offline retry:', cachePath);
   862|          }
   863|        } catch (copyErr) {
   864|          console.log('[PhotoUpload] Queued: could not cache file:', uri, (copyErr as Error)?.message);
   865|        }
   866|      } else if (uri.startsWith('data:image/')) {
   867|        try {
   868|          const match = uri.match(/^data:(image\/[^;]+);base64,(.+)$/);
   869|          if (match) {
   870|            const ext = getMimeAndExt(uri).ext;
   871|            const cachePath = `${FileSystem.cacheDirectory}queued_b64_${Date.now()}_${Math.random().toString(36).substring(2, 6)}.${ext}`;
   872|            await FileSystem.writeAsStringAsync(cachePath, match[2] ?? '', {
